import{_ as a,o as t,c as l,a4 as o}from"./chunks/framework.DzJZdBQK.js";const u=JSON.parse('{"title":"写作课作业-105","description":"","frontmatter":{"date":"2021-02-24T20:55:37","title":"写作课作业-105","categories":["写作","作业","区块链小白书"],"tags":["写作","作业","区块链小白书"]},"headers":[{"level":2,"title":"2W1H","slug":"_2w1h","link":"#_2w1h","children":[{"level":3,"title":"What","slug":"what","link":"#what","children":[]},{"level":3,"title":"Why","slug":"why","link":"#why","children":[]},{"level":3,"title":"How","slug":"how","link":"#how","children":[]}]},{"level":2,"title":"知识点","slug":"知识点","link":"#知识点","children":[]},{"level":2,"title":"我的思考","slug":"我的思考","link":"#我的思考","children":[]}],"relativePath":"posts/homework/105.md","filePath":"posts/homework/105.md"}'),h={name:"posts/homework/105.md"};function i(r,e,p,n,s,c){return t(),l("div",null,[...e[0]||(e[0]=[o('<blockquote><p>《区块链小白书》之《比特币1.问题与解决方案》</p></blockquote><h2 id="_2w1h" tabindex="-1">2W1H <a class="header-anchor" href="#_2w1h" aria-label="Permalink to &quot;2W1H&quot;">​</a></h2><h3 id="what" tabindex="-1">What <a class="header-anchor" href="#what" aria-label="Permalink to &quot;What&quot;">​</a></h3><p>人类的进步史，本质上就是 「发现问题与解决问题」 的历史。</p><p>比特币是中本聪针对一个必须解决的真问题给出的一个完美且无副作用的解决方案。</p><h3 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to &quot;Why&quot;">​</a></h3><p>人类的进步史，本质上就是 「发现问题与解决问题」 的历史。有些是「伪问题」，不需要解决；有些真问题被识别成“伪问题”，找不到解决方案；有些真问题也不需要解决方案，但必须解决的真问题，还需注意解决方案的副作用。</p><h3 id="how" tabindex="-1">How <a class="header-anchor" href="#how" aria-label="Permalink to &quot;How&quot;">​</a></h3><p>通过对「自由意志」的哲学问题，说明“伪问题”不需要解决。</p><p>通过「上火」和「炎症」的对比，说明把真问题识别成「伪问题」时解决方案层出不穷，但不能真正解决问题。使用「幸亏」来转折，「炎症」有实际已然普及的解决方案。</p><p>使用「更令人头痛的是，竟然」来转折，并举例对QWERT键盘布局的改良的尝试，说明尝试的改良是无效的。</p><p>用递进的方式「还要注意另一个问题」，解决必须解决的真问题时，需要注意解决方案的副作用。松花鱼成为传说的例子，说明解决方案的副作用很大。</p><p>最好引出，比特币是对一个必须解决的真问题给出的一个完美且无副作用的解决方案。</p><h2 id="知识点" tabindex="-1">知识点 <a class="header-anchor" href="#知识点" aria-label="Permalink to &quot;知识点&quot;">​</a></h2><ul><li><p>人类的进步史，本质上就是 “发现问题与解决问题” 的历史。</p></li><li><p>伪问题不需要解决；被识别成伪问题的真问题，解决不了；有些真问题也不要解决；必须解决的真问题，需要注意副作用。</p></li></ul><h2 id="我的思考" tabindex="-1">我的思考 <a class="header-anchor" href="#我的思考" aria-label="Permalink to &quot;我的思考&quot;">​</a></h2><p>看这段文字，想到的是：</p><blockquote><p>因为最重要的问题从未被认真对待，于是这个问题就像种子发芽一样，地上长成了参天大树，地下盘根错节，衍生出无数的 “新” 问题…… 于是，我们能看到的情况是一模一样的，人们在地面上围着这盘根错节的 “问题之树”，想出了无数 “解决方案”，每天花大量的时间和精力做着徒劳无益的事情。</p></blockquote><blockquote><p>对定投策略的任何改良都是徒劳。</p></blockquote><p>先把问题搞清楚，才有可能有正确的解。最近小孩写作业的时候，就比较明显的感受到题不懂，就乱做。有时我们自己在生活和工作中也是没认真分析问题，感觉是很使劲了，但事情就是没有办好，没有朝期望的方向发展。</p><hr><p>欢迎联系我</p><p>微信号 ：Crazy_Airhead</p><p>Mixin ID : 1091586</p><p>定投课堂邀请码：6DYMBFP061</p><p>李笑来写作课邀请码：38MDGFYZK8</p><p>水龙头邀请码：FDJQHJ</p>',27)])])}const _=a(h,[["render",i]]);export{u as __pageData,_ as default};
